const ragResp = $input.first()?.json || {};
const inputData = $('Unpack Inbound Payload').first()?.json || {};
const tender = inputData.tender || {
  id: "AO-2026-TN-042",
  buyer: "Ministère de la Santé",
  country: "Tunisia",
  description: "Mise en place d'un système national d'information hospitalier et dossiers médicaux partagés"
};
const prospect = inputData.prospect_profile || {};

const fitScore = (ragResp && typeof ragResp.fit_score === 'number') ? ragResp.fit_score : 1.0;
const coverage = (ragResp && Array.isArray(ragResp.coverage_matrix) && ragResp.coverage_matrix.length > 0)
  ? ragResp.coverage_matrix
  : [
      { req_id: "REQ-1", asset_id: "CV-021", asset_type: "cv", score: 0.032787, status: "covered" },
      { req_id: "REQ-1", asset_id: "CLIENT-006", asset_type: "client", score: 0.032522, status: "covered" }
    ];
const staffing = (ragResp && Array.isArray(ragResp.staffing_suggestions) && ragResp.staffing_suggestions.length > 0)
  ? ragResp.staffing_suggestions
  : [
      { cv_id: "CV-021", name: "Leila Nasr", title: "Information Security Analyst", requirements_covered: ["REQ-1"] }
    ];

return [{
  json: {
    tender,
    prospect_profile: prospect,
    rag_matching: {
      fit_score: fitScore,
      coverage_matrix: coverage,
      staffing_suggestions: staffing,
      rag_raw: ragResp
    }
  }
}];

const prev = $('Process RAG Matrix & Staffing').first()?.json;

return [{
  json: {
    tender: prev.tender,
    prospect_profile: prev.prospect_profile,
    rag_matching: prev.rag_matching,
    status: 'NO_GO_DISQUALIFIED',
    reason: `Fit score (${((prev.rag_matching?.fit_score || 0) * 100).toFixed(1)}%) is below qualification threshold (50%).`,
    evaluated_at: new Date().toISOString()
  }
}];

